# 在来源中添加自定义材料信息
- name: Add custom materials to provenance
  run: |
    # 记录构建时依赖的外部来源
    cat > custom-materials.json << 'EOF'
    [
      {
        "uri": "pkg:npm/lodash@4.17.21",
        "digest": {
          "sha512": "abc123..."
        }
      },
      {
        "uri": "pkg:docker/node:18-alpine@sha256:def456...",
        "digest": {
          "sha256": "def456..."
        }
      }
    ]
    EOF
